contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint addAmount) public payable {
        require(address(this).balance >= addAmount);
        require(addAmount > 0);

        c.addToBalance{value: addAmount}();

        uint recordedBefore =
            c.getBalance(address(this));
        uint contractBalanceBefore =
            address(c).balance;

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(contractBalanceBefore - address(c).balance == recordedBefore);
        } else {
            assert(address(c).balance == contractBalanceBefore && c.getBalance(address(this)) == recordedBefore);
        }
    }

    receive() external payable {}
}

